// Supported authority is a fresh Match/current cityCount0 before road mutation; physical road geometry is separate.
internal sealed class SourceFreshInitialRoadOwner:IDisposable{
 readonly RoadNetworkCompositionSystemHelper network=new RoadNetworkCompositionSystemHelper();readonly Dictionary<string,string> inputs=new Dictionary<string,string>(StringComparer.Ordinal);readonly string output;readonly float roadGridSize;readonly int cityCount;SourceFreshRoadProjection projection;EntityManager manager;Entity grid;bool synced,poisoned,disposed;JObject receipt;
