  string roadText=Read(Path.Combine(root,Road)),cityText=Read(Path.Combine(root,City));
  string roadGuid=Guid(Read(Path.Combine(root,Road+".meta"))),cityGuid=Guid(Read(Path.Combine(root,City+".meta")));
  RequireReference(text,"roadBuildConfig",roadGuid);RequireReference(text,"runtimeCitySpawnerConfig",cityGuid);
  RequireReference(roadText,"m_Script",Guid(Read(Path.Combine(sourceRoot,"Assets/Game/Scripts/Configs/Scene/RoadBuildSystemSceneConfigAsset.cs.meta"))),true);
  RequireReference(cityText,"m_Script",Guid(Read(Path.Combine(sourceRoot,"Assets/Game/Scripts/Configs/Scene/RuntimeCitySpawnerSystemSceneConfigAsset.cs.meta"))),true);
