 }
 static string Absolute(string p){if(string.IsNullOrEmpty(p)||!Path.IsPathRooted(p))throw new ArgumentException("Absolute source road path required");return Path.GetFullPath(p);}
 string Read(string p,string expected=null){p=Absolute(p);var f=new FileInfo(p);if(!f.Exists||f.Length<1||f.Length>4*1024*1024||(f.Attributes&FileAttributes.ReparsePoint)!=0)throw new NotSupportedException("Bounded regular road source required");byte[] raw=File.ReadAllBytes(p);string sha=AutonomousWorld.Hash(raw);if(raw.LongLength!=f.Length||raw.Length>4*1024*1024||expected!=null&&sha!=expected)throw new InvalidOperationException("Road source pin changed: "+p);if(inputs.TryGetValue(p,out string prior)&&prior!=sha)throw new InvalidOperationException("Mixed road source epochs");inputs[p]=sha;return new UTF8Encoding(false,true).GetString(raw);}
 static string Guid(string s){var m=Regex.Matches(s,@"(?m)^guid: ([0-9a-f]{32})\r?$");if(m.Count!=1)throw new NotSupportedException("Unique authored road asset identity required");return m[0].Groups[1].Value;}
 static void RequireReference(string s,string field,string guid,bool script=false){string pattern=@"(?m)^  "+Regex.Escape(field)+@": \{fileID: "+(script?"11500000":"11400000")+@", guid: "+guid+@", type: "+(script?"3":"2")+@"\}\r?$";if(Regex.Matches(s,pattern).Count!=1)throw new NotSupportedException("Actual source road config reference required: "+field);}
