 static float ParseFloat(string s,string field){float f=float.Parse(Scalar(s,field),NumberStyles.Float,CultureInfo.InvariantCulture);if(float.IsNaN(f)||float.IsInfinity(f))throw new NotSupportedException("Finite source road scalar required");return f;}
 void Write(string stage,JObject value){File.WriteAllText(Path.Combine(output,"initial-road-"+stage+".json"),value.ToString());}
 internal void VerifyInputs(){foreach(var pin in inputs)if(AutonomousWorld.Hash(File.ReadAllBytes(pin.Key))!=pin.Value)throw new InvalidOperationException("Road source drift: "+pin.Key);}
 internal void Preflight(){if(disposed||poisoned)throw new InvalidOperationException("Initial road owner unavailable");VerifyInputs();RequireEmpty();}
 void RequireEmpty(){if(network.NextStrokeId!=1||network.RoadTiles.Count!=0||network.Strokes.Count!=0||network.StrokeIdsByCell.Count!=0||network.EdgeCounts.Count!=0||network.AutobahnCells.Count!=0||network.AutobahnConnectorCells.Count!=0)throw new NotSupportedException("Nonempty/modified initial road state requires original mutation/restore/footprint owners before any ECS write");}
 internal void Sync(EntityManager em,Entity target){Preflight();if(synced)throw new InvalidOperationException("Initial road projection sync occurs once");if(em==null||!em.Exists(target))throw new InvalidOperationException("Same real source grid required");var cfg=em.GetComponentData<GridConfig>(target);int n=checked(cfg.Width*cfg.Height);using(var q=em.CreateEntityQuery(typeof(GridConfig),typeof(GridRoad),typeof(GridRoadSidewalk),typeof(GridRoadDirt))){if(q.IsEmptyIgnoreFilter||q.GetSingletonEntity()!=target)throw new InvalidOperationException("Unique same canonical road grid required");}if(em.GetBuffer<GridRoad>(target).Length!=n||em.GetBuffer<GridRoadSidewalk>(target).Length!=n||em.GetBuffer<GridRoadDirt>(target).Length!=n)throw new NotSupportedException("Complete original road buffers required");
  manager=em;grid=target;projection=new SourceFreshRoadProjection(em);try{projection.SyncRoadCellsToEcs(new SourceFreshRoadProjection.Context(network,roadGridSize));synced=true;receipt=Receipt();Write("sync",receipt);Console.WriteLine("[InitialRoadProjection] "+receipt.ToString(Newtonsoft.Json.Formatting.None));}catch{poisoned=true;throw;}
 }
 string BufferHash<T>(Func<int,byte> get,int n){var b=new byte[n];for(int i=0;i<n;i++)b[i]=get(i);return AutonomousWorld.Hash(b);}
 internal JObject Receipt(){if(!synced)throw new InvalidOperationException("Initial road source projection not executed");RequireEmpty();int n=manager.GetBuffer<GridRoad>(grid,true).Length;var r=manager.GetBuffer<GridRoad>(grid,true);var s=manager.GetBuffer<GridRoadSidewalk>(grid,true);var d=manager.GetBuffer<GridRoadDirt>(grid,true);return new JObject{["stage"]="initial_roads_owner",["status"]="PassedFreshEmptyProjection",["actual_original_sync_executed"]=true,["grid_entity"]=grid.Index+":"+grid.Version,["cells"]=n,["tiles"]=network.RoadTiles.Count,["strokes"]=network.Strokes.Count,["city_count"]=cityCount,["roads_sha256"]=BufferHash<GridRoad>(i=>r[i].Value,n),["sidewalks_sha256"]=BufferHash<GridRoadSidewalk>(i=>s[i].Value,n),["dirt_sha256"]=BufferHash<GridRoadDirt>(i=>d[i].Value,n),["source_input_pins"]=JObject.FromObject(inputs),["nonempty_road_mutation_supported"]=false,["physical_campaign_road_geometry"]="Separate source domain; no absence claim"};}
 internal void RequireBeforePath(){if(!synced||disposed||poisoned)throw new InvalidOperationException("Original initial-road sync must precede actors/path");RequireEmpty();}
