}
internal sealed partial class AutonomousWorld{
 SourceFreshInitialRoadOwner initialRoads;
 internal void PrepareFreshInitialRoads(JObject run){if(initialRoads!=null||initializationAttempted||Session!=Entity.Null||Buildings.Count!=0)throw new InvalidOperationException("Prepare fresh road authority before initialization");initialRoads=new SourceFreshInitialRoadOwner(run);}
